Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_vector_reset_iterator_valid_vector(void) {
    Vector* vec = helper_create_vector(0);
    TEST_ASSERT_NOT_NULL(vec);

    int values[] = {10, 20, 30};
    int ret = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, ret);

    int len_result = len(vec);
    TEST_ASSERT_EQUAL_INT(3, len_result);

    int first_next = next(vec);
    TEST_ASSERT_EQUAL_INT(10, first_next);

    int second_next = next(vec);
    TEST_ASSERT_EQUAL_INT(20, second_next);

    vector_reset_iterator(vec);

    int after_reset_next = next(vec);
    TEST_ASSERT_EQUAL_INT(10, after_reset_next);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_vector_reset_iterator_valid_vector);
    return UNITY_END();
}

