// Asserts that vector contents at given index match expected value
void assert_vector_contents(Vector* vec, int index, int expected_value) {
    int actual_value = vec->contents[index];
    TEST_ASSERT_EQUAL_INT(expected_value, actual_value);
}

// Asserts that vector length matches expected value
void assert_vector_length(Vector* vec, int expected_length) {
    int actual_length = vec->len;
    TEST_ASSERT_EQUAL_INT(expected_length, actual_length);
}

// Asserts that vector is empty using vector_is_empty function
void assert_vector_empty(Vector* vec) {
    TEST_ASSERT_NOT_NULL(vec);
    if (vec == NULL) return;
    TEST_ASSERT_EQUAL_INT(0, vec->len);
}

// ========== Created - Utility Operations ==========

// Creates and initializes a Vector with given initial value
Vector* helper_create_vector(int initial_value) {
    Vector* vec = (Vector*)malloc(sizeof(Vector));
    if (vec == NULL) return NULL;
    int result = init(vec, initial_value);
    if (result == -1) {
        free(vec);
        return NULL;
    }
    return vec;
}

// Fills a Vector with multiple values using push function
int helper_fill_vector(Vector* vec, int* values, int count) {
    for (int i = 0; i < count; i++) {
        int result = push(vec, values[i]);
        if (result == -1) {
            // Clean up any partially allocated memory
            // No cleanup here; let caller handle cleanup
            return -1;
        }
    }
    return 0;
}

// Cleans up a Vector by calling delete and freeing the struct
void helper_cleanup_vector(Vector* vec) {
    if (vec != NULL) {
        delete(vec);  // Properly clean up vector contents
        free(vec);    // Free the struct itself
    }
}

